"4-Achs-Sätze mit X/Y/Z und A zusammen: Viele Steuerungen rechnen dort Grad wie Millimeter, der Fräser läuft dann am Werkstück zu langsam oder zu schnell. „Umgerechnet“ schreibt den F-Wert so, dass eine solche Steuerung den gewünschten Vorschub an der Schneide fährt. „Zeitreziprok“ schaltet auf G93 und gibt in jedem Satz 1/Zeit an – eindeutig, wenn die Steuerung G93 kennt.":"4-axis blocks with X/Y/Z and A together: many controls count degrees like millimeters there, so the cutter runs too slow or too fast on the workpiece. “Converted” writes the F value so that such a control runs the desired feed at the cutting edge. “Inverse time” switches to G93 and gives 1/time in every block – unambiguous if the control knows G93.",
