"Abstand Anfang / Ende":"Offset start / end",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Offset start / end turns the flange into a partial flange. Further closed profiles in the sketch become cut-outs in the plate. Holes and windows in a flange: center along the edge (on a curved edge along the arc), center from the end of the bend, size – they appear in the flat pattern too. Where a curved edge passes into its neighboring edge without a kink and both carry a flange with the same bend angle, the flanges run into each other without a relief. “Outline from sketch” cuts the closed profiles of a sketch out of the flange: its X runs along the edge, its Y into the flange, the origin lies at the start of the edge on the end of the bend (can be moved).",
