"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"Reset all settings, toolbar customizations and custom keyboard shortcuts to the defaults?\n\nCustom tool libraries, materials and templates are kept.",
"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Select all faces of the feature: for a hole the wall (and counterbore, bottom), for a pocket the walls and floor, for a boss the side and end face. The feature moves by X/Y/Z; the old location is closed. Also works on imported STEP parts without history. The first time, the large geometry kernel loads (a few seconds).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Select all faces that are to disappear (for a pocket the walls and floor, for a hole the wall, for a fillet the rounded face). The neighboring faces are extended across the gap. The step recomputes when the body changes; the first time the full geometry kernel is loaded for this (a few seconds).",
