"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"Turning: polar interpolation on (X diameter, C in mm; empty = X/C in degrees)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"Turning: finishing cycle (contour of the roughing cycle)",
