"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Turning: Z in front of the face at which the turret indexes. 0 = safety distance + 100 mm",
"Drehen: Zylinder-Interpolation aus":"Turning: cylindrical interpolation off",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"Turning: cylindrical interpolation on ({cylr} = radius; empty = Z/C without)",
"Drehen: angetriebenes Werkzeug und C-Achse aus":"Turning: live tool and C axis off",
"Drehen: einen Winkel angeben.":"Rotate: enter an angle.",
"Drehgelenk":"Revolute",
"Drehgelenk angelegt – mit dem Regler bewegen.":"Revolute joint created – move it with the slider.",
"Drehgeschwindigkeit":"Orbit speed",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Lathe with a Y axis: wrench flats, contours and pockets on the face run with the part standing still (C fixed) in X and Y – more accurate than polar interpolation. What exceeds the Y travel stays with polar interpolation.",
"Drehmeißel":"Turning tool",
