"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Collar {0}: pilot hole Ø {1} mm is widened to Ø {2} mm (factor {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Collar {0}: lies {1} mm from the border (less than 2 × sheet thickness) – the border bulges.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Collar {0}: too high for this hole (the pilot hole would have no diameter left)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Collar: the rim of a round hole is drawn up into a collar, for example as an extruded hole for a thread. The hole diameter of the sketch is the finished inside diameter; the smaller pilot hole is cut in the blank.",
