"Eigene":"Own",
"Eigene Akzentfarbe":"Own accent color",
"Eigene Befehle":"Custom commands",
"Eigene Farbe":"Own color",
"Eigene Kopie „{0}“ angelegt{1} (auch in der Bibliothek) – der eingebaute Postprozessor bleibt unverändert":"Custom copy “{0}” created{1} (also in the library) – the built-in post processor remains unchanged",
"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Custom shortcuts: open the group menu (▾) in the toolbar, click ⋮ next to the command → “Change keyboard shortcut …”.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Your own dimensions and notes can be dragged on the sheet with the mouse (distance of the dimension line, angle of the leader, radius of the angle arc). Click two corners = linear dimension. Click a circle edge in the top view = diameter (or radius). Angle: first the corner, then one corner point on each leg. Chamfer: both ends of the slanted edge – gives e.g. 2×45°. The text field after each dimension holds a suffix such as ±0,1, H7 or 4×.",
"Eigene Regel":"Custom rule",
"Eigene Symbolfarbe":"Own icon color",
"Eigene Werte":"Custom values",
"Eigene Werte (unten)":"Own values (below)",
"Eigene {0} mm":"Custom {0} mm",
