"Erst Schritte anlegen.":"Create steps first.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"First click the face on the body that is moved, then the target face on the other body. The body is rotated and moved until the first click point lies on the second and the faces lie on each other.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"First click the edge on the body that is moved, then the target edge on the other body. Straight edges are made coincident (center on center); for circular edges – hole and pin – the axes are aligned and the center points brought together.",
"Erst ein Setup anlegen.":"Create a setup first.",
"Erst ein Setup mit Operationen anlegen.":"Create a setup with operations first.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Select a sketch or construction plane first – then Ctrl+8 looks straight at it.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"First create a body in DESIGN or insert a mesh (STL).",
