"Erzeugt eine neue Fläche im Abstand zu den gewählten Flächen (negativ = nach innen). Der Körper bleibt unverändert.":"Creates a new surface at a distance from the selected faces (negative = inwards). The body remains unchanged.",
"Erzeugt einen Tastzyklus (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).":"Creates a probing cycle (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).",
