"Fläche anklicken, die ersetzt wird.":"Click the face to be replaced.",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Click a face: at every clicked point the clearance hole for the screw (ISO 273, medium series) is made through all parts lying on each other there – with a 90° countersink for countersunk screws, and for cap screws optionally with a counterbore (DIN 974-1, series 1) as deep as the head. The screw sits in it right away. Hole and screw can be changed afterwards in the timeline.",
"Fläche anpassen":"Fit Surface",
"Fläche anpassen: eine Freiformfläche durch die Punkte einer Punktwolke legen":"Fit Surface: fit a freeform surface through the points of a point cloud",
