"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Click a face of a body: its boundary is added to the sketch as an outline. Clicking an edge projects only that edge (circles stay circles). Projected geometry is purple.",
"Fläche ersetzen":"Replace face",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Replace face: move a planar face onto another plane – the body grows or is shortened",
"Fläche extrudieren":"Extrude face",
