"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Fusion 360 files (.f3d) are a proprietary Autodesk format and cannot be read.\n\nIn Fusion 360: choose File → Export → STEP (.stp) and import that file here.",
