"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Follows all sharp outer edges reachable from above and breaks them by the deburr depth – with a chamfer mill as a chamfer (tool axis vertical, tip outside the edge), with a ball/lollipop mill rounded.",
