"Gemeinsame Schnittkanten nur einmal schneiden":"Cut common edges only once",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Common cut edges: if two blanks lie exactly one kerf apart (enter the kerf as the spacing when nesting), their paths coincide on the shared edge and it is cut only once. The lead-in never lies in a neighboring part: if there is no free waste beside a contour, the pierce is made on the contour. After “Preview”, a picture per sheet shows the path before the files are saved.",
