"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Straight lines of the sketch that belong to no profile (construction lines too). Bend: the line is the middle of the bend zone and the sketch is the blank there – the largest piece of the plate stays where it is, everything beyond the line swings along with its flanges. The line applies across the whole plate. Bead: a rib along the line, round in section and at its ends; the sheet keeps its thickness.",
"Gerade Nuten (Langloch oder Linie mit Nutbreite) gehen als Nutzyklus der Steuerung heraus.":"Straight slots (slot shape or line with slot width) are output as the control's slot cycle.",
