"Geschlossen":"Closed",
"Geschlossen (Gehrung)":"Closed (miter)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Closed: flanges on two neighboring edges run up to the angle bisector of the corner and leave the gap free there. The corner relief sits where the bend zones cross – in the flat pattern and in the folded part. A flange on a curved edge is mitred at a real corner as well (without corner relief there).",
"Geschlossene Hohlräume im Inneren des Körpers werden mit Material gefüllt.":"Closed voids inside the body are filled with material.",
"Geschlossene Kette {0}":"Closed chain {0}",
"Geschlossene Profile begrenzen den Bereich.":"Closed profiles bound the area.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Fill closed profiles of the active sketch with color",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Closed profiles become planar surfaces – e.g. top and bottom caps, to stitch surfaces into a body afterwards.",
"Geschnitten ab X":"Sectioned from X",
"Geschwenkte Bearbeitungsebene":"Tilted working plane",
"Geschwindigkeit der Animation":"Animation speed",
"Geschätzte Bearbeitungszeit (Klick: Details)":"Estimated machining time (click: details)",
