"Gespeichert werden Blechdicke {0} mm, Biegeradius innen {1} mm und K-Faktor {2}. Die Regel steht danach bei jedem Blech in der Liste „Blechregel“ – auch in anderen Projekten auf diesem Rechner.":"Saved are sheet thickness {0} mm, inner bend radius {1} mm and K-factor {2}. After that the rule is in the list “Sheet metal rule” of every sheet metal part – also in other projects on this computer.",
"Gespiegelt":"Mirrored",
"Gestrichelt im DXF/der Skizze: Biegelinien (Anfang und Ende jeder Biegezone). Im DXF liegen sie auf der Ebene BIEGUNG, der Umriss auf Ebene 0.":"Dashed in the DXF/sketch: bend lines (start and end of every bend zone). In the DXF they are on the layer BIEGUNG, the outline on layer 0.",
"Gewebe":"Web",
"Gewebe: alle offenen Linien einer Skizze werden zu Rippen":"Web: all open lines of a sketch become ribs",
