"Gewindebohrung für {0}":"Tapped hole for {0}",
"Gewindebohrung für {0} – Skizze":"Tapped hole for {0} – sketch",
"Gewindebohrung im untersten Teil":"Tapped hole in the lowest part",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Tapped hole in the lowest part: the clearance hole ends where the lowest part begins; there the tap drill hole with its thread is made – three thread turns deeper than the screw reaches, or through the whole part. If only one part lies under the point, it gets the thread from its face on. “Length to suit the thread engagement” takes the next length of the series with which the screw sits about as deep in the thread as its thread is thick (a guide value for steel) – but never longer than the part is thick.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"tapped hole {0} – thread engagement only {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"tapped hole {0}, thread engagement {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Tapped hole: the tap drill hole is drilled; the thread appears as a cosmetic thread on the model and with its name in the drawing.",
