"Gleich":"Equal",
"Gleich gerichtet (statt gegenüber)":"Same direction (instead of opposed)",
"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Equal diameters give a tube, different ones the frustum of a cone. The flat pattern is calculated on the neutral fiber (inner face + K-factor × sheet thickness); in rolling it lies closer to the middle of the sheet than in press braking – a K-factor of 0.45 to 0.5 is usual. With a sheet metal rule its thickness and K-factor apply. The seam gap stays open at the larger diameter (0 = butt joint, in the body then a slit of 0.01 mm).",
"Gleicher Abstand":"Equal distance",
"Gleichlauf":"Climb",
"Gleichmäßige Dreiecke dieser Größe: lange Kanten werden geteilt, danach wird auf die Dreieckszahl eines gleichmäßigen Netzes reduziert. Gut vor dem Glätten oder Formen von Scans.":"Even triangles of this size: long edges are split, then the mesh is reduced to the triangle count of an even mesh. Good before smoothing or shaping scans.",
"Gleichzeitig mit dem Schritt davor":"Simultaneous with the previous step",
