"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: enable data transfer over Ethernet on the control (as for TNCremo, LSV2, port 19000); default folder TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: port 21, folder e.g. /_N_WKS_DIR or /NC. Network folder: path like \\\\MASCHINE\\NC or Z:\\NC. DNC: converter as TCP server (raw), usually port 4001; on the control start “Program run external”, DNC or TAPE.",
