"Integriert":"Built-in",
"Interferenz":"Interference",
"Interferenz braucht mindestens zwei Körper.":"Interference needs at least two bodies.",
"Inventor (Mitte verschieben, Umschalt+Mitte drehen)":"Inventor (middle pan, Shift+middle orbit)",
"Invers Verschleiß":"Inverse wear",
"Invertieren (helle Linien auf dunklem Grund)":"Invert (light lines on a dark background)",
"Isokurven":"Isocurves",
"Isokurven auf den gekrümmten Flächen":"Isocurves on the curved faces",
"Isokurven: Linien gleicher Flächenparameter auf den gekrümmten Flächen.":"Isocurves: lines of constant surface parameter on the curved faces.",
"Isolieren":"Isolate",
"Isometrie":"Isometric view",
"Isometrisch":"Isometric",
"Isometrische Ansicht":"Isometric view",
"Istwert":"Actual value",
"J (relativ)":"J (relative)",
"JSON kopieren":"Copy JSON",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Two Q parameters per operation at the start of the program: the first shifts the depth (DL, + = less deep), the second the side stock (DR, + = more stock; works only with radius compensation in the control RL/RR). Change one number on the machine instead of searching blocks.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"The first curve of each sketch – open or closed. The curves are joined by a skin (surface without thickness).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"One file per sheet. The path runs beside the outline by half the kerf (half the cutter when routing), in the waste; cut-outs come before the outline of their part, every contour starts with a lead-in from the waste. Louvre slits are cut on their line. Tabs: that many places per outline are left standing (laser, plasma, waterjet: the beam pauses there; routing: the cutter lifts to half the sheet thickness); outlines shorter than 40 mm get none. “Control” sets how the beam is switched on and off; the pierce time is written as G4 unless the control pierces by itself. The origin is the lower left corner of the sheet, when routing Z0 is the top of the sheet. Verify the program on the machine or in an NC simulator before use.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"All parts per tool (fewer tool changes)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Each axis separately: click an edge, corner, face or hole. Axes not set are taken from the stock point.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Each hole is approached individually with its coordinates (X/Y per hole) – no bolt circle or grid pattern.",
"Jede Fläche des Körpers wird ein eigener Flächenkörper.":"Every face of the body becomes a separate surface body.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Each operation as a subprogram (LBL) at the end of the program, called with CALL LBL",
"Jede Variante berechnen und als STEP, STL oder 3MF speichern (eine ZIP-Datei)":"Compute each variant and save it as STEP, STL or 3MF (one ZIP file)",
"Jede offene Linie der Skizze wird zu einer Rippe – ein ganzes Rippennetz in einem Schritt.":"Every open line of the sketch becomes a rib – a whole web of ribs in one step.",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Every circle of the sketch is a hole center. Holes are drilled against the sketch normal (into the material).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Every circle of the sketch is repeated, turned around the center (in sketch coordinates) – a circle at the distance of the pitch circle radius gives a bolt circle.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Every circle of the sketch becomes a grid: spacings in X and Y of the sketch (negative values allowed).",
"Jeder Körper in einer eigenen Farbe":"Each body in its own color",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Every visible body becomes a link with a mesh (STL, in meters), mass and inertia, every joint a joint with axis and limits. The present pose is the zero pose. With a package name the URDF names the meshes as package://Name/meshes/…, otherwise by a relative path.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Each # in the sketch text is replaced by the number, padded with zeros (SN-#### → SN-{0}). With several parts in one setup each part gets the next number: {1}{2}.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Each part has its own work offset in the control (G54, G55 … or preset number in the table – Heidenhain cycle 247). Set all work offsets on the machine first.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Each own dimension and each tolerance frame gets a number in a circle. The list contains nominal size, tolerance, maximum and minimum size and fields for the actual value. Dimensions without their own tolerance get the general tolerance.",
"Jetzigen Stand festhalten":"Keep the present state",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Now pick a point on the second leg.",
"Jetzt festhalten":"Keep now",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Now move each direction once to the limit: slide, pull, push, tilt, twist (10 s) …",
"Jetzt laden":"Download now",
"Jetzt nach Updates suchen":"Check for updates now",
"Jetzt senden":"Send now",
