"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"Calibrate: real distance between the two points (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Calibrate: click two points in the image whose distance is known and enter the real distance – the image gets the correct scale.",
