"Kante als Kreis projiziert":"Edge projected as a circle",
"Kante am bewegten Körper gewählt":"Edge on the moving body selected",
"Kante im Blatt anklicken …":"Click an edge on the sheet …",
"Kante projiziert":"Edge projected",
"Kante {0} (Bogen R{1}, {2} mm)":"Edge {0} (arc R{1}, {2} mm)",
"Kante {0} (Kreis R{1}, {2} mm)":"Edge {0} (circle R{1}, {2} mm)",
"Kante {0} ({1} mm)":"Edge {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"Edge {0} is too short for a flange",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Edge {0}: a bend angle above 180° cannot be made.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Edge {0}: flange on a curved edge – its rim is compressed by {1} % during forming (risk of wrinkles); the blank is an approximation there.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Edge {0}: flange on a curved edge – its rim is stretched by {1} % during forming (risk of cracks); the blank is an approximation there.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Edge {0}: the flange dimension {1} mm is smaller than the bend ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Edge {0}: the arc is too tight for this flange",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Edge {0}: the offsets leave no flange.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Edge {0}: the flange crosses a bend line – let it end before the bend with “Distance start / end”",
"Kante {0}: die Lasche liegt in einer Biegezone":"Edge {0}: the flange lies in a bend zone",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Edge {0}: a cut-out belongs to a flange that does not exist.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Edge {0}: a cut-out in the flange lies {1} mm next to the bend (less than 2 × sheet thickness) – it distorts when bending.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Edge {0}: a cut-out lies {1} mm next to the bend (less than 2 × sheet thickness) – it distorts when bending.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Edge {0}: a cut-out extends beyond the flange.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Edge {0}{1}: flange {2} mm is shorter than 2 × sheet thickness – hardly bendable on a press brake.",
"Kante {0}{1}: Saum {2} mm ist kürzer als 4 × Blechdicke – er lässt sich schlecht zudrücken.":"Edge {0}{1}: hem {2} mm is shorter than 4 × sheet thickness – it is hard to press shut.",
"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"Edge {0}{1}: closed hem (inner radius {2} mm) – it is bent in two strokes and pressed shut; hard materials crack on the outside in doing so.",
"Kante: {0} · Länge {1} mm":"Edge: {0} · Length {1} mm",
"Kanten":"Edges",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"Edges (lines coincident, circles concentric)",
"Kanten abrunden: „Verrundung“ (F), einige Kanten anklicken, Radius z. B. 3 mm, OK.":"Round edges: “Fillet” (F), click some edges, radius e.g. 3 mm, OK.",
"Kanten anklicken (erneut klicken entfernt).":"Click edges (click again to remove).",
"Kanten anklicken zum Hinzufügen oder Entfernen – das Ergebnis erscheint gleich im Modell. Kanten, die vor dem Befehl angeklickt wurden, sind schon gewählt. Eingabe = OK.":"Click edges to add or remove them – the result shows in the model right away. Edges clicked before the command are already selected. Enter = OK.",
