"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Release the cap and choose “Calibrate zero point”. Then try each direction: the bar should move and stay within the gray dead zone at rest.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Slide the cap = pan, push/pull = zoom, tilt and twist = rotate the model. In sketches only pan and zoom. SpaceMouse Pro/Enterprise: T, F, R = top, front, right view. If nothing happens: briefly quit the 3Dconnexion driver and reconnect.",
