"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Contour with {0} points – Okuma: G85 (LAP) with contour G81…G80, Fanuc: G71 P…Q…. The control roughs with its own cut distribution; the simulation here is the WerkFab path.",
"Kontur zum Freifräsen davor anlegen":"Add a clearing contour before it",
"Kontur {0}":"Outline {0}",
"Konturauswahl":"Contour selection",
"Konturen außen und innen":"Outer and inner outlines",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Outlines follow the border of the dark areas. The center line runs along the middle of the strokes – suitable for engravings and line drawings. “Lines, arcs and circles” detects straight edges, sharp corners, curves and circles; “Polylines” follows the image point by point. Afterwards adjust the scale with “Calibrate reference image” or “Scale” if needed.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Contours with cutter compensation in the control (RL/RR) lead in and out with APPR/DEP; the control calculates auxiliary point and compensation itself",
"Konturschlichten":"Contour finishing",
"Konturzug ({0} Kontur{1}) – Heidenhain: CYCL DEF 14 + 25, die Kontur als Unterprogramm (LBL) mit R{2}. Der Radius wird an der Steuerung korrigiert.":"Contour train ({0} contour{1}) – Heidenhain: CYCL DEF 14 + 25, the contour as a subprogram (LBL) with R{2}. The radius is compensated on the control.",
