"Kugel":"Sphere",
"Kugel teilen":"Split sphere",
"Kugel-, Schaft-, Torus- oder Konusfräser. Ein Kugelfräser behält seine Bahn; andere Fräser werden geneigt und entlang ihrer Achse verschoben, bis sie am Teil anliegen, ohne es zu verletzen. Höchstens die größte Neigung; wo Schaft oder Halter das Teil berühren würden, richtet sich das Werkzeug auf. Ausgabe als Werkzeugvektor (Heidenhain, Sinumerik, Fanuc), sonst als 3-Achs-Bahn.":"Ball, flat, bull nose or tapered end mill. A ball end mill keeps its path; other cutters are tilted and moved along their axis until they touch the part without gouging it. At most the largest tilt; where the shank or the holder would touch the part, the tool stands up again. Output as a tool vector (Heidenhain, Sinumerik, Fanuc), otherwise as a 3-axis path.",
