"Kurven":"Curves",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Curves of a sketch on the face (across the rotary axis) with a live cutter along Z (X and C move together; Fanuc: polar interpolation G12.1). Open curves are milled back and forth. Depth from the face.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Curves of a sketch lying along the rotary axis are wrapped onto the circumference and milled with a live cutter pointing at the axis (Z and C move together; Fanuc: cylindrical interpolation G7.1). The sketch plane defines the angle at which the contour sits; horizontal lines in the sketch become arcs around the part. Depth from the outer diameter.",
"Kurzbefehl":"Shortcut",
"Kurze Aufgaben direkt in WerkFab. Ein Fenster zeigt den nächsten Schritt und hakt ihn selbst ab, sobald er erledigt ist; der passende Knopf blinkt.":"Short lessons right inside WerkFab. A window shows the next step and ticks it off by itself once it is done; the matching button flashes.",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Short moves (up to the stay-down distance) are made down at the transition feed rate instead of via the retract height – without collision check, so keep it small.",
