"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Flange on flange: angle + bends on in the same direction (U-channel, fold with 180°), − in the opposite direction (Z step, hat section). Hem: the edge of the flange is folded back on itself by 180° – open with a gap of one sheet thickness, closed pressed flat; with − 180° it lies on the other side. The field R is the inner radius of this bend only (empty = as for the sheet). For a hem directly on the edge of the plate set the flange itself to 180°. Jog: two bends against each other (− 45° and + 45°) – the edge runs on parallel and offset; the offset follows from the length of the slanted piece and the angles.",
"Lasche {0}":"Flange {0}",
"Laschen, die über eine Biegelinie laufen, sind dort geteilt und freigestellt.":"Flanges that run across a bend line are split and relieved there.",
