"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Several connected edges count as one path: the radius runs from the start of the chain to its end, control points are given in % of the whole chain length. This is computed by the full geometry kernel.",
"Mehrfachaufspannung":"Multiple parts",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Multiple parts: this control has no work offset for part {0} – only one part output",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Multiple parts: this post processor has no datum shift – choose “Own work offset per part”; only one part output",
"Meine Designs · {0}":"My designs · {0}",
"Meine Werkzeuge":"My tools",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Reports paths that cut deeper than the model at that place (end mills, face mills, ball and bull nose cutters, chamfer mills and drills with their cone; 3-axis moves). A cut that is not in the model – an engraving, a dog-bone relief, a pocket from a sketch only – is reported too.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Message on the screen of the control: Fanuc and LinuxCNC as (MSG, …), Sinumerik as MSG(\"…\"), otherwise as a comment.",
