"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"With control points the radius runs through the given values (position in % of the edge length). This is computed by the full geometry kernel; the first time it takes a few seconds to load.",
"Mit dem 3D-Taster kann nicht zerspant werden":"The 3D probe cannot be used for cutting",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Compare with the finished part: green = to size, blue = rest material, red = too deep",
"Mit dem Reiter „{0}“ vergleichen?\n\nAbbrechen = eine Datei wählen":"Compare with the tab “{0}”?\n\nCancel = choose a file",
"Mit dem Werkzeug-Taster (TT) direkt nach dem TOOL CALL: Q340=1 prüft gegen die Werkzeugtabelle, schreibt die Abweichung als DL/DR und sperrt das Werkzeug bei überschrittener Verschleiß- oder Bruchtoleranz":"With the tool touch probe (TT) right after the TOOL CALL: Q340=1 checks against the tool table, writes the deviation as DL/DR and locks the tool when the wear or breakage tolerance is exceeded",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Move the mouse next to a contour (the side sets the direction) · Esc to finish",
"Mit diesem Werkzeug kann nicht gefräst werden":"This tool cannot be used for milling",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"With a tap use only the “Tapping” cycle – a drilling cycle would break it",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"With several passes the thread depth is milled in steps that each remove about the same amount – easier on small thread mills and in hard materials. The spring pass runs the last path once more without infeed.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"With “Drilling cycles” in the NC program, control cycles are output (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), otherwise expanded moves.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"With “Keep original” the original and its mirror image become one mesh; points on the mirror plane are joined – an open half becomes a closed part.",
