"Nur die Registerkarten zeigen (mehr Platz); ein Klick auf eine Karte klappt sie auf":"Show only the tabs (more room); clicking a tab expands it",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Retrace only those parts of the contour that a larger cutter could not reach (inside corners, narrow areas). Without lead-in/lead-out arcs, tabs and finishing passes; compensation in computer.",
"Nur die gewählten Körper werden beim Bewegen gegeneinander geprüft (keiner gewählt = alle). Das macht die Prüfung bei großen Baugruppen schnell.":"Only the selected bodies are checked against each other while moving (none selected = all). This keeps the check fast for large assemblies.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Only where the reference tool could not reach: shallow areas parallel, steep areas as waterline. With a tool from the list its shape counts too – for example what a bull-nose cutter leaves in the fillets.",
