"Nut liegt nicht am Teil":"Slot is not on the part",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Slot along the rotary axis (e.g. keyway) with a live cutter pointing at the axis; the main spindle holds the part as C axis. Slot width = cutter Ø. Start/end Z in model Z; if the slot reaches the face, the cutter enters from the front, otherwise it plunges at the start. Depth from the outer diameter.",
