"Schruppt die Bohrung von der Vorbohrung nach außen (0,2 mm Schlichtaufmaß) und schlichtet sie dann bis zum Grund. Die Bohrstange muss in die Vorbohrung passen.":"Roughs the bore from the pre-drilled hole outwards (0,2 mm finishing allowance), then finishes it down to the bottom. The boring bar must fit into the pre-drilled hole.",
"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"Roughs in simultaneous 4-axis from the outside in: one spiral around the A axis per stepdown (alternating in +X and −X), never deeper than the part plus stock to leave. With flat or ball end mill.",
