"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Pocket on the circumference from the closed contours of a sketch that lies along the turning axis (inner contours stay as islands). The sketch is wrapped onto the diameter; a driven flat end mill pointing at the axis clears from the inside out (Z and C move together; Fanuc: cylindrical interpolation G7.1). The cutter enters on a ramp along the innermost ring.",
"Tasche gespiegelt":"Mirrored pocket",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Pocket in the face from the closed contours of a sketch (inner contours remain as islands), with a live flat end mill along Z. Clearing runs from the inside out; the cutter ramps in along the innermost pass and stays down within a level. X and C move together (Fanuc: polar interpolation G12.1). Depth from the face.",
"Tasche mit Insel":"Pocket with island",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"Pocket with island – the control cycle cannot handle islands",
