"Vernetzung fehlgeschlagen:":"Tessellation failed:",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Really computes two closed meshes with each other: faces lying inside disappear, the intersection edges are re-meshed. Only the region where the two meshes can meet is computed – so a large mesh with a small intervention is fast. If two large meshes overlap entirely, “Reduce” first.",
