"Verschleiß":"Wear",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Bolted joint: washers and nut go onto every clicked hole together with the screw. The clamped thickness is the length of the hole – through several parts if their holes are in line and meet. With a nut, the shortest preferred length is proposed at which the screw protrudes two thread turns from the nut.",
"Verschraubung: {0} – Klemmdicke {1} mm":"Bolted joint: {0} – clamped thickness {1} mm",
"Verschraubung: {0} – die Schraube ist für die Klemmdicke {1} mm zu kurz (nötig: {2} mm)":"Bolted joint: {0} – the screw is too short for the clamped thickness of {1} mm (required: {2} mm)",
