"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Wraps the sketch curves onto the cylinder: X stays X, the distance across the axis becomes an arc on the wrapping Ø (rotation A). The sketch must be parallel to the A axis, e.g. on a tangent plane. Milling runs at a fixed depth below the part surface – for engravings, lettering and slots around the part.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Like 3D contour, but the tool moves down continuously without steps – no plunge marks on steep walls.",
