"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"How finely cylinders, spheres and fillets are made of triangles in the view. Finer looks rounder but takes longer on large models. Export has its own setting (3D printing).",
