"Zahnform nach Tredgold (Ersatz-Stirnrad auf dem Rückenkegel), gerade Zähne. Das große Ende liegt in der Grundebene, die Zähne laufen zur Kegelspitze. Für Darstellung, 3D-Druck und Fräsen aus dem Vollen; geschliffene Kegelräder brauchen die Daten des Herstellers.":"Tooth form after Tredgold (equivalent spur gear on the back cone), straight teeth. The large end lies in the base plane, the teeth run towards the cone apex. For display, 3D printing and milling from solid; ground bevel gears need the data of the manufacturer.",
