"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Tabs stand out at the free end of the flange and go into the flat pattern. “Slots as sketch” creates the matching slots where the tabs stand – one sketch per plane, every slot larger than the tab by the clearance all round. Draw the outline of the mating part in this sketch and make a sheet or an extrusion from it: the slots become cut-outs. The mating part rests on the ends of the flanges; the tab length usually equals its thickness.",
