"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"“+” = tool will be created. Cutting data are guide values for carbide ({0}){1}; coolant: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"“Nest into each other” lays the blanks into the gaps and bays of their neighbors and into their cut-outs (without turning by 90° only turned round by 180°); the spacing is never undercut. Without the tick they lie in rows by their bounding rectangle. “Sketch + bodies” creates flat bodies of the sheet thickness that can be cut out in manufacturing with 2D contour.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"“Inside/Outside” needs closed contours – mill open curves with “On the curve”",
"„Prüfen“ fährt den Ablauf in kleinen Zeitschritten ab und meldet, wann welche Körper zusammenstoßen.":"“Check” runs the sequence in small time steps and reports when which bodies collide.",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"“Finish sketch” → Extrude, Revolve or Hole.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"“Sketch” → choose plane XY/XZ/YZ or click a planar face.",
